const { app, BrowserWindow, ipcMain, screen, dialog, shell } = require("electron");
const fs = require("fs");
const os = require("os");
const path = require("path");

let win = null;
let dragState = null;

/** Window / taskbar icon, generated by tools/make_icon.py. */
const APP_ICON = path.join(__dirname, "assets", "icon.png");

/**
 * The directory the folder button opens before the user picks their own.
 *
 * Deliberately derived at runtime instead of hardcoded: an absolute path baked
 * into the source only ever works on the machine that wrote it. Falls back to
 * the home directory when the platform reports no Documents folder.
 */
function defaultOpenDir() {
  try {
    return app.getPath("documents");
  } catch (e) {
    return os.homedir();
  }
}

// 默认位置：屏幕右侧、中上方（harness 浏览器窗口一般偏左，右侧留出来给鲸鱼娘）
function defaultPosition() {
  const wa = screen.getPrimaryDisplay().workArea;
  const W = 288;
  return {
    x: wa.x + wa.width - W - 24,
    y: wa.y + Math.round(wa.height * 0.18)
  };
}

// 记忆上次拖动的位置，下次启动还原（夹在屏幕工作区内）
function loadPosition() {
  try {
    const raw = fs.readFileSync(path.join(app.getPath("userData"), "window-pos.json"), "utf8");
    const { x, y } = JSON.parse(raw);
    if (typeof x === "number" && typeof y === "number") {
      const wa = screen.getPrimaryDisplay().workArea;
      const W = 288;
      const H = 300;
      return {
        x: Math.min(Math.max(x, wa.x), wa.x + wa.width - W),
        y: Math.min(Math.max(y, wa.y), wa.y + wa.height - H)
      };
    }
  } catch (e) { /* first run or unreadable -> default */ }
  return defaultPosition();
}

function savePosition() {
  if (!win) return;
  const [x, y] = win.getPosition();
  try {
    fs.writeFileSync(path.join(app.getPath("userData"), "window-pos.json"), JSON.stringify({ x, y }));
  } catch (e) { /* non-fatal */ }
}

function createWindow() {
  const pos = loadPosition();
  win = new BrowserWindow({
    x: pos.x,
    y: pos.y,
    width: 288,
    height: 300,
    icon: APP_ICON,
    transparent: true,
    frame: false,
    resizable: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    hasShadow: false,
    fullscreenable: false,
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false
    }
  });
  win.setAlwaysOnTop(true, "screen-saver");
  // 透明区域默认鼠标穿透：只有悬停到鲸鱼娘/按钮/单词本上时才接管点击
  win.setIgnoreMouseEvents(true, { forward: true });
  win.loadFile("index.html");
}

ipcMain.on("ignore-mouse", (_e, ignore) => {
  if (win) win.setIgnoreMouseEvents(!!ignore, { forward: true });
});

ipcMain.on("quit", () => app.quit());
ipcMain.on("drag-start", (_e, { x, y }) => {
  if (!win) return;
  const [wx, wy] = win.getPosition();
  dragState = { x, y, wx, wy };
});
ipcMain.on("drag-move", (_e, { x, y }) => {
  if (!dragState || !win) return;
  win.setPosition(dragState.wx + (x - dragState.x), dragState.wy + (y - dragState.y));
});
ipcMain.on("drag-end", () => { dragState = null; savePosition(); });

// ── 屏幕底部 galgame 对话框窗口 ─────────────────────────────────────────
let dlg = null;

function createDialogue() {
  const wa = screen.getPrimaryDisplay().workArea;
  const w = Math.round(Math.min(wa.width * 0.86, 1280));
  const h = 172;
  dlg = new BrowserWindow({
    x: wa.x + Math.round((wa.width - w) / 2),
    y: wa.y + wa.height - h - 32,
    width: w,
    height: h,
    icon: APP_ICON,
    transparent: true,
    frame: false,
    resizable: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    hasShadow: false,
    fullscreenable: false,
    focusable: true,
    show: false,
    webPreferences: { nodeIntegration: true, contextIsolation: false }
  });
  dlg.setAlwaysOnTop(true, "screen-saver");
  dlg.loadFile("dialogue.html");
  dlg.on("closed", () => { dlg = null; });
}

ipcMain.on("show-dialogue", (_e, text) => {
  if (!dlg) createDialogue();
  const send = () => { if (dlg) dlg.webContents.send("dialogue-text", text); };
  if (dlg.webContents.isLoading()) dlg.webContents.once("did-finish-load", send);
  else send();
  dlg.showInactive();
});
ipcMain.on("close-dialogue", () => { if (dlg) dlg.hide(); });

// ── 单词本：选择保存文件 / 追加保存 / 窗口随列表自动长高 ──────────────────
ipcMain.handle("pick-file", async (_e, current) => {
  const r = await dialog.showSaveDialog(win, {
    title: "选择单词保存文件",
    defaultPath: current || path.join(app.getPath("documents"), "whale-words.txt"),
    filters: [
      { name: "文本文件", extensions: ["txt"] },
      { name: "所有文件", extensions: ["*"] }
    ]
  });
  return r.canceled ? null : r.filePath;
});
ipcMain.handle("append-file", async (_e, { path: filePath, text }) => {
  await fs.promises.appendFile(filePath, text, "utf8");
  return true;
});
ipcMain.on("resize", (_e, { w, h }) => {
  if (!win) return;
  win.setSize(
    Math.max(288, Math.round(w)),
    Math.max(214, Math.min(820, Math.round(h)))
  );
});

// ── 📁 打开文件夹（桌宠上灯泡下面那个按钮）──────────────────────────────
// 先校验路径再交给系统打开，这样渲染进程能拿到「不存在 / 不是文件夹」这类
// 具体原因，用自己的气泡说出来，而不是静默失败。
ipcMain.handle("default-dir", () => defaultOpenDir());

ipcMain.handle("open-dir", async (_e, dir) => {
  const target = String(dir || "").trim();
  if (!target) return { ok: false, error: "还没设定文件夹" };
  let st = null;
  try {
    st = fs.statSync(target);
  } catch (e) {
    return { ok: false, error: "路径不存在" };
  }
  if (!st.isDirectory()) return { ok: false, error: "这不是文件夹" };
  const err = await shell.openPath(target); // 成功时返回空字符串
  return err ? { ok: false, error: err } : { ok: true };
});

// 让用户指定「点一下要打开哪个文件夹」
ipcMain.handle("pick-dir", async (_e, current) => {
  const start = current && fs.existsSync(current) ? current : undefined;
  const r = await dialog.showOpenDialog(win, {
    title: "选择点击后要打开的文件夹",
    defaultPath: start,
    properties: ["openDirectory"]
  });
  return r.canceled || !r.filePaths.length ? null : r.filePaths[0];
});

// 单实例：重复启动时退出新实例，并把已有鲸鱼娘带到前台（防止按钮连点开多个）
if (!app.requestSingleInstanceLock()) {
  app.quit();
} else {
  app.on("second-instance", () => {
    if (!win) return;
    if (win.isMinimized()) win.restore();
    win.show();
    win.focus();
  });
  app.whenReady().then(createWindow);
  app.on("window-all-closed", () => { if (process.platform !== "darwin") app.quit(); });
}
